settings.custom_css:
selector .elementor-tab-title { padding: 18px 20px !important; border-radius: 14px !important; margin-bottom: 10px !important; background: #F3F8FB !important; transition: all .3s ease; }
selector .elementor-tab-title .elementor-tab-number { color: #B7C3CB !important; font-weight: 800 !important; margin-right: 10px; }
selector .elementor-tab-title.elementor-active { background: #09171F !important; }
selector .elementor-tab-title.elementor-active .elementor-tab-number { color: rgba(255,255,255,.5) !important; }
selector .elementor-tabs-content-wrapper { background: #FFFFFF !important; border-radius: 20px !important; padding: 44px !important; box-shadow: 0 20px 50px -24px rgba(9,23,31,.35); }
@media(max-width:767px){ selector .elementor-tabs-content-wrapper{ padding:26px !important; } }
